"""Join the engine and the panel UI into one installable After Effects panel: dist/BQ Kinetic.jsx.
   python tools/make_panel.py"""
import os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
engine = open(os.path.join(ROOT, "engine", "bq_kinetic.jsx"), encoding="utf-8").read()
panel = open(os.path.join(ROOT, "panel", "panel_ui.jsx"), encoding="utf-8").read()
head = ("// BQ Kinetic: build kinetic-type films in After Effects from a director's JSON (bq-kinetic/1).\n"
        "// Generated by tools/make_panel.py from engine/bq_kinetic.jsx + panel/panel_ui.jsx. Do not edit by hand.\n")
src = head + engine.rstrip() + "\n\n" + panel
bad = [i for i, c in enumerate(src) if ord(c) > 127]
if bad:
    sys.exit("non-ASCII character at offset %d: %r (After Effects scripts must stay ASCII)" % (bad[0], src[bad[0]]))
os.makedirs(os.path.join(ROOT, "dist"), exist_ok=True)
out = os.path.join(ROOT, "dist", "BQ Kinetic.jsx")
with open(out, "w", encoding="ascii", newline="\n") as f:
    f.write(src)
print("wrote", out, len(src), "bytes")
